 80→/**
 81→ * Hook that is meant to be used in any component that renders a popover element. Used to track which popovers are
 82→ * currently open in the top layer.
 83→ */
 84→export const usePopoverTracker = (active: boolean) => {
 85→  const context = React.use(TopLayerContext);
 86→  
 87→  // When `active` changes, sync up with the context
 88→  React.useEffect(() => {
 89→    if (context === null) { return; } // May sometimes become `null` even if a Provider is present in the tree?
 90→    if (active) {
 91→      context.modalDialogStack.publish();
 92→    }
 93→  }, [context, active]); 
 94→};
