 42→const usePageHistory = <D extends object, PageHistoryItem extends object>() => {
 43→  type PageIndex = number;
 44→  
 45→  // Note: conceptually the page history should be a stack. However, in order to prevent timing issues, we maintain
 46→  // a map keyed with the page index, rather than an array. This allows us to handle situations where our local state
 47→  // is out of sync with the actual table state.
 48→  const [pageHistory, setPageHistory] = React.useState<Map<PageIndex, PageHistoryItem>>(() => new Map());
 49→  
 50→  const truncateToPage = React.useCallback(
 51→    (pageHistory: Map<PageIndex, PageHistoryItem>, pageIndex: PageIndex) => {
 52→      const keys = [...pageHistory.keys()];
 53→      if (keys.length === 0 || keys[keys.length - 1] === pageIndex) {
 54→        return pageHistory; // Don't update if we don't need to (optimization)
 55→      }
 56→        return new Map([...pageHistory.entries()].filter(([pageIndexCurrent]) => pageIndexCurrent <= pageIndex));
 57→    },
 58→    [],
 59→  );
 60→  
 61→  // Present an interface conceptually similar to a stack, but also take explicit page indices for consistency checking
 62→  const pageHistoryApi = (pageHistory: Map<PageIndex, PageHistoryItem>) => ({
 63→    clear: () => {
 64→      const history = new Map();
 65→
 66→      return pageHistoryApi(history);
 67→    },
 68→    pop: (pageIndex: PageIndex) => {
 69→      const history = truncateToPage(pageHistory, pageIndex);
 70→
 71→      return pageHistoryApi(history);
 72→    },
 73→    push: (pageIndex: PageIndex, pageHistoryItem: PageHistoryItem) => {
 74→      const indices = [...pageHistory.keys()];
 75→      // biome-ignore lint/style/noNonNullAssertion: <explanation>
 76→      const lastIndex: PageIndex = indices[indices.length - 1]!;
 77→      // Make sure the page indices are contiguous
 78→      if (pageIndex > lastIndex + 1) {
 79→        throw new Error('Non-contiguous page indices'); // Should never happen
 80→      }
 81→
 82→      const history = new Map(pageHistory).set(pageIndex, pageHistoryItem);
 83→
 84→      return pageHistoryApi(history);
 85→    },
 86→    peak(pageIndex: PageIndex): null | PageHistoryItem {
 87→      return pageHistory.get(pageIndex) ?? null;
 88→    },
 89→    get: () => pageHistoryApi(pageHistory),
 90→    write: () => {
 91→      setPageHistory(pageHistory);
 92→    },
 93→  });
 94→  
 95→  return pageHistoryApi(pageHistory);
 96→};
