19→// Extend `HTMLOrSVGElement` focus options with `focusVisible`
20→interface FocusOptions {
21→  focusVisible?: undefined | boolean,
22→}
23→
24→// Extend `HTMLElement` with `togglePopover` variant that accepts an object. Remove this once TypeScript adds support:
25→// https://github.com/microsoft/TypeScript/blob/d0d675a363bf25d435857766757d97b9ad508909/src/lib/dom.generated.d.ts#L14240
26→type TogglePopoverOptions = {
27→  force?: undefined | boolean,
28→  // NOTE: `source` must be an `HTMLElement`, not just any `Element`. If given, for example, an `<svg>` element, the
29→  // browser will throw an exception.
30→  source?: undefined | HTMLElement,
31→};
32→interface HTMLElement {
33→  togglePopover(options?: undefined | TogglePopoverOptions ): boolean,
34→}
35→

