  2→|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of
  3→|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */
  4→
  5→import * as React from 'react';
  6→
  7→
  8→export type ModalDialogController = {
  9→  /** Whether the dialog should be active. */
 10→  active: boolean,
 11→  /** Notify that the dialog has been opened. Change must be respected (otherwise no longer in sync). */
 12→  activate: () => void,
 13→  /** Notify that the dialog has been closed. Change must be respected (otherwise no longer in sync). */
 14→  deactivate: () => void,
 15→};
 16→
 17→export type UseModalDialogOptions = {
 18→  /**
 19→   * Whether to allow the user to close the modal through the browser (e.g. with the Escape key). Disabling this may
 20→   * be useful in cases where we need the user to stay in the modal (e.g. form validation, mandatory onboarding flows).
 21→   * Note: closing cannot be always be prevented (e.g. browser may force the dialog to close, or closed through JS).
 22→   */
 23→  allowUserClose?: undefined | boolean,
 24→  
 25→  /** Whether the user clicking the backdrop should close the modal. Only valid if `allowUserClose` is true. */
 26→  shouldCloseOnBackdropClick?: undefined | boolean,
 27→};
 28→
 29→export type ModalDialogProps = {
 30→  internalDialogRef: React.RefObject<null | HTMLDialogElement>,
 31→  close: () => void,
 32→  dialogProps: React.ComponentProps<'dialog'>,
 33→};
 34→
 35→/*
 36→ * A utility hook to control the state of a <dialog> element used as a modal (with `.showModal()`).
 37→ */
 38→export const useModalDialog = (
 39→  controller: ModalDialogController,
 40→  options: undefined | UseModalDialogOptions = {},
 41→): ModalDialogProps => {
 42→  const {
 43→    allowUserClose = true,
 44→    shouldCloseOnBackdropClick = true,
 45→  } = options;
 46→  
 47→  const dialogRef = React.useRef<HTMLDialogElement>(null);
 48→  //const lastActiveElementRef = React.useRef<Element>(null); // Note: browsers track this automatically now
 49→  
 50→  const requestDialogClose = React.useCallback(() => {
 51→    const dialog = dialogRef.current;
 52→    if (!dialog) { console.warn(`Unable to close dialog: reference does not exist.`); return; }
 53→    
 54→    try {
 55→      dialog.close();
 56→    } catch (error: unknown) {
 57→      console.error(`Failed to close dialog`, error);
 58→    }
 59→  }, []);
 60→  
 61→  // Sync active state with <dialog> DOM state
 62→  const sync = () => {
 63→    const dialog = dialogRef.current;
 64→    if (!dialog) { return; } // Nothing to sync with
 65→    
 66→    const isDialogOpenModal = dialog.open && dialog.matches(':modal');
 67→    
 68→    if (controller.active && !isDialogOpenModal) { // Should be active but isn't
 69→      // Save a reference to the last focused element before opening the modal
 70→      //lastActiveElementRef.current = document.activeElement;
 71→      
 72→      // Note: `showModal()` may throw, for example if the dialog is already open as a non-modal (through `.show()`),
 73→      // or as a popover (through `.showPopover()`).
 74→      try {
 75→        dialog.open = false; // Make sure the dialog is not open as a non-modal (i.e. through `.show()`)
 76→        dialog.showModal();
 77→      } catch (error: unknown) {
 78→        console.error(`Unable to open modal dialog`, error);
 79→        controller.deactivate();
 80→      }
 81→    } else if (!controller.active && isDialogOpenModal) { // Should not be active but is
 82→      requestDialogClose();
 83→    }
 84→  };
 85→  // biome-ignore lint/correctness/useExhaustiveDependencies: `controller` is used in `sync`
 86→  React.useEffect(sync, [controller]);
 87→  
 88→  // The `beforetoggle` event can be used to detect when a modal opens. Note: browser support is poor currently, but
 89→  // it's okay since we generally control the activation, not the user. In non-supporting browsers, if someone were to
 90→  // manually call `.showModal()` through devtools they could potentially cause a desync.
 91→  // https://caniuse.com/mdn-api_htmlelement_toggle_event_dialog_elements
 92→  const handleDialogBeforeToggle = React.useCallback((event: React.ToggleEvent<HTMLDialogElement>) => {
 93→    if (event.newState === 'open') {
 94→      controller.activate();
 95→    }
 96→  }, [controller]);
 97→  
 98→  // Handle dialog `cancel` event. This event is called when the user requests the dialog to close (e.g. with Escape
 99→  // key). Can be canceled, though browsers do not always respect the cancelation (e.g. Chrome still closes when the
100→  // Escape key is hit twice).
101→  // https://developer.mozilla.org/en-US/docs/Web/API/HTMLDialogElement/close_event
102→  const handleDialogCancel = React.useCallback((event: React.SyntheticEvent<HTMLDialogElement>) => {
103→    if (!allowUserClose) {
104→      event.preventDefault();
105→    }
106→  }, [allowUserClose]);
107→  
108→  // Handle dialog `close` event. This event is called when the dialog has already been closed (cannot be canceled).
109→  // https://developer.mozilla.org/en-US/docs/Web/API/HTMLDialogElement/close_event
110→  const handleDialogClose = React.useCallback((event: React.SyntheticEvent<HTMLDialogElement>) => {
111→    // Stop this event from closing parent dialog elements
112→    // XXX `close` events shouldn't bubble, but at least in Chrome v131 it seems like it does?
113→    event.stopPropagation();
114→    
115→    /*
116→    // XXX This is probably not necessary, browsers do this out of the box already
117→    // Restore focus to last active element before the user opened the modal
118→    const lastActiveElement = lastActiveElementRef.current;
119→    if (lastActiveElement && 'focus' in lastActiveElement && typeof lastActiveElement.focus === 'function') {
120→      lastActiveElement.focus();
121→    }
122→    */
123→    
124→    // Note: browsers do not automatically close nested modals. Instead, we need to do this manually
125→    if (event.target instanceof HTMLElement) {
126→      // Note: in the future (once browser support is available), we can just do:
127→      //event.target.querySelectorAll(':open').forEach(element => { element.requestClose(); });
128→      
129→      event.target.querySelectorAll('dialog[open]').forEach(element => {
130→        if (element instanceof HTMLDialogElement) {
131→          element.close();
132→        }
133→      });
134→    }
135→    
136→    controller.deactivate(); // Sync with the controller
137→  }, [controller]);
138→  
139→  // Handle dialog `click` event
140→  const handleDialogClick = React.useCallback((event: React.MouseEvent<HTMLDialogElement>) => {
141→    const dialog: HTMLDialogElement = event.currentTarget;
142→    const target: EventTarget = event.target;
143→    
144→    // We want to determine whether the click was on the `<dialog>` backdrop. For the event, the backdrop is considered
145→    // just a part of the `<dialog>` element. So we need to check both that the target is the `<dialog>` *and also*
146→    // that the click landed outside of the element content boundary.
147→    // Source: https://stackoverflow.com/questions/25864259/how-to-close-dialog-tag-by-clicking-on-its-backdrop
148→    let isClickOnBackdrop = false;
149→    if (target === dialog) {
150→      const rect = dialog.getBoundingClientRect();
151→      const isInsideDialog = rect.top <= event.clientY
152→        && event.clientY <= rect.top + rect.height
153→        && rect.left <= event.clientX
154→        && event.clientX <= rect.left + rect.width;
155→      isClickOnBackdrop = !isInsideDialog;
156→    }
157→    
158→    if (allowUserClose && shouldCloseOnBackdropClick && isClickOnBackdrop) {
159→      event.stopPropagation();
160→      event.preventDefault();
161→      controller.deactivate();
162→    }
163→  }, [controller, allowUserClose, shouldCloseOnBackdropClick]);
164→  
165→  // Handle dialog `keydown` event
166→  const handleDialogKeyDown = React.useCallback((event: React.KeyboardEvent<HTMLDialogElement>) => {
167→    if (event.key === 'Escape' && !allowUserClose) {
168→      event.preventDefault();
169→    }
170→  }, [allowUserClose]);
171→  
172→  // Sync when the ref changes. This helps prevent time issues where `active` is set to `true`, but the dialog is not
173→  // yet mounted (and thus the ref is `null`). In that case our sync `useEffect` will be too early.
174→  const dialogRefCallback: React.RefCallback<HTMLDialogElement> = (ref) => {
175→    dialogRef.current = ref;
176→    sync();
177→  };
178→  
179→  return {
180→    close: requestDialogClose,
181→    internalDialogRef: dialogRef, // Note: should not pass this to the dialog `ref`, use `dialogProps.ref` instead
182→    dialogProps: {
183→      ref: dialogRefCallback,
184→      open: undefined, // Do not set `open`, leave it to the browser to manage automatically
185→      
186→      onBeforeToggle: handleDialogBeforeToggle,
187→      onCancel: handleDialogCancel,
188→      onClose: handleDialogClose,
189→      // Note: we don't need keyboard accessibility for this `onClick`, the backdrop is not (and should not be) an
190→      // interactive element. This is a visual only convenience, screen readers should use the other close mechanisms.
191→      onClick: shouldCloseOnBackdropClick ? handleDialogClick : undefined,
192→      onKeyDown: handleDialogKeyDown,
193→    },
194→  };
195→};
196→

