 4→
 5→import * as React from 'react';
 6→import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
 7→import { useScroller } from '../../../layouts/util/Scroller.tsx';
 8→
 9→import { H4 } from '../../../typography/Heading/Heading.tsx';
10→
11→import cl from './Panel.module.scss';
12→
13→
14→export { cl as PanelClassNames };
15→
16→
17→export type PanelHeadingProps = React.PropsWithChildren<ComponentProps<typeof H4>>;
18→export const PanelHeading = (props: PanelHeadingProps) => {
