 38→  const {
 39→    children,
 40→    unstyled = false,
 41→    compact = false,
 42→    arrow,
 43→    size = undefined,
 44→    ...propsRest
 45→  } = props;
 46→  
 47→  const scrollerProps = useScroller();
 48→  
 49→  const arrowClassNames = ((): ClassNameArgument => {
 50→    if (!arrow) { return; }
 51→    
 52→    switch (arrow) {
 53→      case 'top': return cx(cl['bk-tooltip--arrow'], cl['bk-tooltip--arrow-top']);
 54→      case 'right': return cx(cl['bk-tooltip--arrow'], cl['bk-tooltip--arrow-right']);
 55→      case 'bottom': return cx(cl['bk-tooltip--arrow'], cl['bk-tooltip--arrow-bottom']);
 56→      case 'left': return cx(cl['bk-tooltip--arrow'], cl['bk-tooltip--arrow-left']);
 57→      default: return assertUnreachable(arrow);
 58→    }
 59→  })();
 60→  
 61→  return (
 62→    <div
 63→      role="tooltip" // https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Roles/tooltip_role
 64→      {...propsRest}
 65→      className={cx(
 66→        'bk',
 67→        { [cl['bk-tooltip']]: !unstyled, },
 68→        { [cl['bk-tooltip--compact']]: compact },
 69→        { [cl['bk-tooltip--small']]: size === 'small' },
 70→        { [cl['bk-tooltip--medium']]: size === 'medium' },
 71→        { [cl['bk-tooltip--large']]: size === 'large' },
 72→        arrowClassNames,
 73→        propsRest.className,
 74→      )}
 75→    >
 76→      <div {...scrollerProps} className={cx(cl['bk-tooltip__content'], 'bk-prose', scrollerProps.className)}>
