42→        unstyled
43→        role="switch"
44→        {...propsRest}
45→        disabled={!isInteractive}
46→        className={cx(
47→          { [cl['bk-switch']]: !unstyled },
48→          propsRest.className,
49→        )}
50→      />
51→    );
52→  },
